'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BASE='<Default>', token=new URLSearchParams(location.hash.slice(1)).get('token')||sessionStorage.getItem('wayricadToken')||'';
if(token){sessionStorage.setItem('wayricadToken',token);history.replaceState(null,'',location.pathname);}
const S={data:null,variant:BASE,view:'bom',selected:new Set(),search:'',filter:'all',sort:'Reference',asc:true,page:0,pageSize:100,
 columns:['Reference','Value','Footprint','MPN','Manufacturer','Assembly','InBOM','UnitPrice','Currency'],template:'',templateDraft:null,variableScope:'project',preview:null,formDirty:false};
const titles={bom:['BOM workspace','Every component, every population decision.'],variants:['Variant management','Inherit deliberately. Compare before you commit.'],variables:['Variables & expressions','Separate project data from workspace and variant overrides.'],sourcing:['Sourcing & alternates','Track purchasing inputs and document substitution decisions.'],exports:['Exports & templates','Build a repeatable handoff, not another one-off spreadsheet.'],checks:['Design checks','Surface incomplete or contradictory BOM data before release.'],review:['Review & native sync','Keep BOM workspace edits separate from changes to your KiCad files.'],about:['Compatibility & help','What this preview supports, and where it deliberately stops.']};
function toast(message,error=false){const d=document.createElement('div');d.className='toast'+(error?' error':'');d.textContent=message;while($('#toasts').children.length>=3)$('#toasts').firstElementChild.remove();$('#toasts').append(d);setTimeout(()=>d.remove(),error?11000:5000);$('#statusLine').textContent=message;}
async function api(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:{'X-Bom-Token':token,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw Error('The local server did not return a valid response. Check the launcher console.');}if(!response.ok)throw Error(data.error||'Operation failed.');return data;}
async function refresh(){S.data=await api('state?variant='+encodeURIComponent(S.variant));if(S.data.project){S.columns=S.data.bom_authority?.preferences.mode==='native'?[...(S.data.view?.columns||[])]:S.data.view?.columns?.length?[...S.data.view.columns]:[...(S.data.field_inventory?.default_columns||[])];if(S.data.bom_authority?.preferences.mode==='native'){S.sort=S.data.view.sort_field;S.asc=S.data.view.sort_asc!==false;}S.legacyLayout=S.data.view?.columns?.length&&!S.data.view?.field_mode;const validIDs=new Set(S.data.rows.map(r=>r.id));S.selected=new Set([...S.selected].filter(id=>validIDs.has(id)));for(const r of S.data.rows)r._searchText=Object.values(r.fields).join(' ').toLowerCase();render();}header();}
function header(){const d=S.data;if(!d?.project)return;$('#projectName').textContent=d.project.name+(d.demo?' · Sample project':'');$('#projectPath').textContent=d.project.path;$('#projectPath').title=d.project.path;$('#saveStatus').textContent=d.dirty?'● Unsaved workspace':'Workspace up to date';$('#saveButton').disabled=false;$('#quickExport').disabled=false;$('#checksCount').textContent=d.issues.filter(i=>i.severity==='error').length||'';}
async function action(path,body={},message='Updated.'){const result=await api(path,{variant:S.variant,...body});await refresh();if(message)toast(typeof message==='function'?message(result):message);return result;}
function variantOptions(value=S.variant){return [BASE,...Object.keys(S.data.variants)].map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v===BASE?'Default assembly':v)}</option>`).join('');}
function pill(state){return `<span class="pill ${esc(String(state).toLowerCase())}">${esc(state)}</span>`;}
function lead(){const [title,description]=titles[S.view];return `<div class="page-head"><div><div class="eyebrow">${S.view==='bom'?'ASSEMBLY INTELLIGENCE':'WAYRICAD BOM STUDIO'}</div><h1>${title}</h1><p>${description}</p></div><div class="variant-switch"><label for="activeVariant">ACTIVE VARIANT</label><select id="activeVariant">${variantOptions()}</select></div></div>`;}
function metrics(){const x=S.data.stats,cost=Object.entries(x.cost).map(([c,v])=>`${esc(c)} ${Number(v).toLocaleString(undefined,{maximumFractionDigits:3})}`).join('<br>')||'Not priced';return `<div class="metrics"><article class="metric"><div class="metric-label">Physical components</div><div class="metric-value">${x.parts}</div><div class="metric-foot">Multi-unit symbols counted once</div></article><article class="metric"><div class="metric-label">Fitted in BOM</div><div class="metric-value">${x.fitted}</div><div class="metric-foot">${x.excluded} excluded from BOM</div></article><article class="metric"><div class="metric-label">Not fitted</div><div class="metric-value">${x.not_fitted}</div><div class="metric-foot">DNP / DNI · separate from BOM exclusion</div></article><article class="metric"><div class="metric-label">Known cost / board</div><div class="metric-value cost">${cost}</div><div class="metric-foot">${x.unpriced} unpriced · ${esc(S.data.analytics_settings?.price_field||'UnitPrice')} mapping · full variant</div></article></div>`;}
function render(){if(!S.data?.project)return;S.formDirty=false;$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===S.view));let content=lead();if(S.data.demo)content+=`<div class="notice">You are exploring a temporary sample copy. Part numbers and prices are fictional demo data; this is not an electrically validated circuit.</div>`;if(S.data.project.blockers.length)content+=`<div class="notice error"><b>Inspection mode.</b> ${esc(S.data.project.blockers[0])} <button class="linkbutton" data-view="checks">See checks →</button></div>`;
 const views={assemblers:()=>renderAssemblers(),vendors:()=>renderVendors(),bom:renderBOM,variants:renderVariants,variables:renderVariables,sourcing:renderSourcing,exports:renderExportsV2,fieldtemplates:renderFieldTemplates,health:renderHealth,analyzer:renderAnalyzer,evidence:renderEvidence,checks:renderChecks,review:renderReview,about:renderAbout,automation:renderAutomation,analytics:renderAnalytics,engineering:renderEngineering};$('#main').innerHTML=content+views[S.view]();header();if(S.view==='about')loadCompatibility();}
function filteredRows(){let rows=S.data.rows.filter(r=>(!S.search||(r._searchText??Object.values(r.fields).join(' ').toLowerCase()).includes(S.search.toLowerCase()))&&(S.filter==='all'||(S.filter==='fitted'&&r.fields.Assembly==='FIT')||(S.filter==='not_fitted'&&r.fields.Assembly!=='FIT')||(S.filter==='excluded'&&!r.flags.in_bom)||(S.filter==='missing_mpn'&&!r.fields.MPN)));rows.sort((a,b)=>String(a.fields[S.sort]??'').localeCompare(String(b.fields[S.sort]??''),undefined,{numeric:true,sensitivity:'base'})*(S.asc?1:-1));return rows;}
function gridTable(rows,columns,selectable=true){return `<table class="data-table"><thead><tr>${selectable?'<th><input type="checkbox" id="selectPage" aria-label="Select visible page"></th>':''}${columns.map(c=>`<th ${S.view==='bom'?`draggable="true" data-grid-column="${esc(c)}" title="Drag to reorder columns"`:''}><button data-sort="${esc(c)}">${esc(c)} ${c===S.sort?(S.asc?'↑':'↓'):''}</button></th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr data-row="${esc(r.id)}" class="${S.selected.has(r.id)?'selected ':''}${r.fields.Assembly!=='FIT'?'not-fitted':''}">${selectable?`<td><input type="checkbox" data-select="${esc(r.id)}" ${S.selected.has(r.id)?'checked':''} aria-label="Select ${esc(r.ref)}"></td>`:''}${columns.map(c=>`<td class="${c==='Reference'?'ref ':''}${['Reference','Qty','Sheet','UUID','Source','Required','OrderQty','LineCost','OrderCost'].includes(c)?'':'editable edit-cell'}" data-field="${esc(c)}" data-id="${esc(r.id)}" title="${esc(r.fields[c])}">${c==='Assembly'?pill(r.fields[c]):typeof r.fields[c]==='boolean'?(r.fields[c]?'Yes':'No'):esc(r.fields[c]||'—')}</td>`).join('')}<td><button class="quiet small" data-inspect="${esc(r.id)}" aria-label="Inspect ${esc(r.ref)}">↗</button></td></tr>`).join('')}</tbody></table>`;}
function renderBOM(){const rows=filteredRows(),pages=Math.max(1,Math.ceil(rows.length/S.pageSize));S.page=Math.min(S.page,pages-1);const shown=rows.slice(S.page*S.pageSize,(S.page+1)*S.pageSize);return metrics()+`<section class="panel"><div class="toolbar"><input class="searchbox" id="search" type="search" value="${esc(S.search)}" placeholder="Search references, values, MPNs…" aria-label="Search BOM"><select id="populationFilter" aria-label="Filter population"><option value="all">All components</option><option value="fitted" ${S.filter==='fitted'?'selected':''}>Fitted</option><option value="not_fitted" ${S.filter==='not_fitted'?'selected':''}>DNP / DNI</option><option value="excluded" ${S.filter==='excluded'?'selected':''}>Excluded from BOM</option><option value="missing_mpn" ${S.filter==='missing_mpn'?'selected':''}>Missing MPN</option></select><span class="grow"></span><button class="small" data-act="undo" ${!S.data.undo?'disabled':''}>↶ Undo</button><button class="small" data-act="redo" ${!S.data.redo?'disabled':''}>↷ Redo</button><button class="small" data-act="columns">Columns</button><button class="small" data-act="import">Import CSV</button></div><div class="selectionbar" ${S.selected.size?'':'hidden'}><b>${S.selected.size} selected</b><button class="small" data-pop="FIT">Fit</button><button class="small" data-pop="DNP">DNP</button><button class="small" data-pop="DNI">DNI</button><button class="small" data-act="bulk">Edit field…</button><button class="quiet small" data-act="clearSelection">Clear</button><span class="grow"></span><span class="fine">Changes affect ${S.variant===BASE?'shared base symbols':'this variant'}.</span></div><div class="table-wrap">${shown.length?gridTable(shown,S.columns):'<div class="empty">No components match this filter.</div>'}</div><div class="table-footer"><span>${rows.length} components · Double-click a cell to edit · ↗ for provenance</span><div class="row"><button class="quiet small" data-act="prevPage" ${!S.page?'disabled':''}>←</button><span>${S.page+1} / ${pages}</span><button class="quiet small" data-act="nextPage" ${S.page>=pages-1?'disabled':''}>→</button></div></div></section>`;}
function showDialog(title,body,onSubmit){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=onSubmit?`<form id="dialogForm">${body}<div class="dialog-error" id="dialogError" role="alert"></div></form>`:body;const dialog=$('#dialog');if(!dialog.open)dialog.showModal();if(onSubmit)$('#dialogForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;try{if(button)button.disabled=true;const submittedForm=e.target;await onSubmit(new FormData(submittedForm));if(document.querySelector('#dialogForm')===submittedForm)dialog.close();}catch(error){const area=document.querySelector('#dialogError');if(area)area.textContent=error.message;else toast(error.message,true);}finally{if(button)button.disabled=false;}});}
const formActions=(text='Save changes')=>`<div class="form-actions"><button type="button" data-act="closeDialog">Cancel</button><button class="primary" type="submit">${text}</button></div>`;
function allFields(){return [...new Set([...S.columns,...S.data.rows.flatMap(r=>Object.keys(r.raw)),...Object.keys(S.data.aliases),'Assembly','InBOM','InPosFiles','OnBoard','ExcludeFromSim'])].filter(k=>!['Reference','UUID','Source','Qty','Sheet'].includes(k)).sort();}
const flagMap={InBOM:'in_bom',OnBoard:'on_board',InPosFiles:'in_pos_files',ExcludeFromSim:'exclude_from_sim',DNP:'dnp'};
function editDialog(ids=[...S.selected],field='MPN'){if(!ids.length){toast('Select at least one component first.');return;}const r=S.data.rows.find(r=>r.id===ids[0]);field=r.field_name_sources?.[field]||field;if((r.generated_fields||[]).includes(field)){toast('Generated KiCad field: the value is linked to its name expression. Edit the project variable, or use Field name templates → Enforce to explicitly rename/bake it.');return;}showDialog(ids.length===1?'Edit '+r.ref:`Edit ${ids.length} selected components`,`<p class="fine">${S.variant===BASE?'Base edits also affect every occurrence of the same shared-sheet symbol.':'Only '+esc(S.variant)+' is changed. Other variants retain their own values.'}</p><div class="field"><label for="editField">Field</label><input name="field" id="editField" list="fieldNames" value="${esc(field)}" required><datalist id="fieldNames">${allFields().map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div><div class="field"><label for="editValue">Value</label><textarea name="value" id="editValue">${esc(ids.length===1?(flagMap[field]?r.flags[flagMap[field]]:r.raw[field]??r.fields[field]??''):'')}</textarea><small>For inclusion flags use true / false. Assembly uses FIT, DNP or DNI.</small></div><label class="check-label"><input type="checkbox" name="reset">${S.variant===BASE?'Remove this workspace override':'Reset this field to the default assembly'}</label>${formActions('Apply to workspace')}`,async form=>{const key=form.get('field').trim();let value=form.get('reset')?null:form.get('value');if(key==='Assembly'&&value!==null){await action('population',{ids,state:value.trim().toUpperCase()},'Population updated.');return;}const target=flagMap[key]||key;if(Object.values(flagMap).includes(target)&&value!==null){if(!/^(true|false|yes|no|1|0)$/i.test(value.trim()))throw Error('Use true or false for inclusion flags.');value=/^(true|yes|1)$/i.test(value.trim());}const changes={[target]:value};if(key==='Assembly'&&value===null)changes.dnp=null;await action('edit',{ids,changes},r=>`${r.affected} component instances updated.`);});}
function inspect(id){const r=S.data.rows.find(r=>r.id===id);showDialog(r.ref+' · Field provenance',`<div class="row">${pill(r.fields.Assembly)}<span class="chip">${r.units} unit${r.units===1?'':'s'}</span><span class="chip">${esc(r.lib_id)}</span></div><div class="spacer"></div><dl class="keyvalue"><dt>Sheet</dt><dd>${esc(r.fields.Sheet)}</dd><dt>Source</dt><dd>${esc(r.fields.Source)}</dd><dt>Instance UUID</dt><dd class="mono">${esc(r.id)}</dd><dt>Inherited restrictions</dt><dd>${esc(r.inherited.join(', ')||'None')}</dd></dl><div class="table-wrap tall"><table class="data-table"><thead><tr><th>Field</th><th>Raw / expression</th><th>Resolved</th><th>Source</th></tr></thead><tbody>${Object.keys(r.fields).map(k=>`<tr><td>${esc(k)}</td><td>${esc(r.raw[k]??'—')}</td><td>${esc(r.fields[k])}</td><td>${esc(r.origins[flagMap[k]||k]||'Native / effective')}</td></tr>`).join('')}</tbody></table></div>`);}
function columnsDialog(){const fields=[...new Set([...S.columns,...S.data.rows.flatMap(r=>Object.keys(r.fields))])];showDialog('Visible BOM columns',`<p class="fine">This changes the workspace view, not the export template.</p><div class="checkbox-grid">${fields.map(k=>`<label class="check-label"><input type="checkbox" name="column" value="${esc(k)}" ${S.columns.includes(k)?'checked':''}>${esc(k)}</label>`).join('')}</div>${formActions('Update columns')}`,async f=>{const columns=f.getAll('column');if(!columns.length)throw Error('Keep at least one column.');S.columns=columns;render();});}
function openDialog(){showDialog('Open KiCad project',`<p class="fine">Choose the root <code>.kicad_sch</code> or its <code>.kicad_pro</code>. Save in KiCad first: the workspace reads files, not unsaved editor memory.</p><div class="field"><label for="projectInput">Absolute file path</label><div class="row"><input class="grow" id="projectInput" name="path" placeholder="C:\\Projects\\Board\\Board.kicad_pro"><button type="button" data-act="browse">Browse…</button></div></div>${S.data?.dirty?'<label class="check-label"><input type="checkbox" name="discard">Discard my unsaved workspace changes</label>':''}<div class="row"><button type="button" data-act="demo">Explore sample project</button></div>${formActions('Open project')}`,async f=>{if(!f.get('path').trim())throw Error('Choose or enter a project path.');await api('open',{path:f.get('path').trim().replace(/^"|"$/g,''),discard:f.has('discard')});S.variant=BASE;S.selected.clear();await refresh();toast('Project loaded. Native files have not been changed.');});}
function newVariantDialog(){showDialog('Create an assembly variant',`<div class="field"><label>Name</label><input name="name" required placeholder="e.g. Flight, Qualification, Economy" maxlength="128"></div><div class="field"><label>Inherit from</label><select name="parent">${variantOptions()}</select><small>Changes to the parent flow through until a field is overridden. Native sync flattens inheritance into KiCad-compatible differentials.</small></div><div class="field"><label>Description</label><textarea name="description" placeholder="What makes this assembly different?"></textarea></div>${formActions('Create variant')}`,async f=>{const result=await api('variant/add',{name:f.get('name'),parent:f.get('parent'),description:f.get('description')});S.variant=result.name;await refresh();toast('Variant created in the workspace.');});}
function renderVariants(){const names=[BASE,...Object.keys(S.data.variants)];return `<div class="split"><section><div class="row spread"><h2>Assemblies</h2><button class="primary small" data-act="newVariant">+ New variant</button></div><div class="spacer"></div>${names.map(v=>`<article class="variant-card ${v===S.variant?'active':''}"><div class="row spread"><button class="linkbutton" data-choose-variant="${esc(v)}"><b>${esc(v===BASE?'Default assembly':v)}</b></button>${v===BASE?'':`<span class="pill">${S.data.variants[v].native?'Native':'Workspace'}</span>`}</div><small>${v===BASE?'Source of default fields and population':`Inherits ${esc(S.data.variants[v].parent===BASE?'Default':S.data.variants[v].parent)}`}</small><p class="fine">${esc(S.data.variants[v]?.description||'')}</p>${v!==BASE&&!S.data.variants[v].native?`<button class="quiet small" data-remove-variant="${esc(v)}">Remove workspace variant</button>`:''}</article>`).join('')}<div class="notice"><b>DNI is a workspace distinction.</b> Both DNP and DNI map to native KiCad DNP, while the <code>Assembly</code> field preserves your intended label.</div></section><section class="panel"><div class="panel-title"><h2>Compare assemblies</h2><span class="chip">Field-level comparison</span></div><div class="panel-body"><div class="row"><select id="compareLeft" aria-label="Baseline variant">${variantOptions(BASE)}</select><span>→</span><select id="compareRight" aria-label="Comparison variant">${variantOptions()}</select><button class="primary small" data-act="compareVariants">Compare</button><button class="small" data-act="populationMatrix">Population matrix</button></div><div id="variantComparison" class="spacer"></div><p class="fine">The active variant below is editable. Use the variant selector to inspect another assembly.</p><div class="table-wrap tall">${gridTable(S.data.rows.slice(0,250),['Reference','Value','Assembly','InBOM','MPN','Footprint'],false)}</div>${S.data.rows.length>250?'<p class="fine">Showing the first 250 components. The main BOM grid and exports cover the entire project.</p>':''}</div></section></div>`;}
function diffTable(changes){if(!changes.length)return '<div class="notice">No differences found.</div>';return `<p class="fine">${changes.length} field differences</p><div class="table-wrap tall"><table class="data-table"><thead><tr><th>Reference</th><th>Field</th><th>Before</th><th>After</th></tr></thead><tbody>${changes.map(c=>`<tr><td class="ref">${esc(c.Reference)}</td><td>${esc(c.Field)}</td><td>${esc(c.Before)}</td><td>${esc(c.After)}</td></tr>`).join('')}</tbody></table></div>`;}
function variableValues(){if(S.variableScope==='project'){const values={...S.data.project_variables};for(const [k,v]of Object.entries(S.data.project_variable_edits)){if(v===null)delete values[k];else values[k]=v;}return values;}if(S.variableScope==='workspace')return S.data.workspace_variables;return S.data.variants[S.variant]?.variables||{};}
function variableRow(k='',v=''){return `<div class="variable-row"><input aria-label="Variable name" data-variable-key value="${esc(k)}" placeholder="NAME"><input aria-label="Variable value" data-variable-value value="${esc(v)}" placeholder="Value or \${OTHER_VARIABLE}"><button class="quiet" data-act="removeVariable" aria-label="Remove variable">×</button></div>`;}
function renderVariables(){const values=variableValues(),scope=S.variableScope;return `<div class="columns2"><section class="panel"><div class="panel-title"><h2>Variable editor</h2><select id="variableScope" aria-label="Variable scope"><option value="project" ${scope==='project'?'selected':''}>Project variables</option><option value="workspace" ${scope==='workspace'?'selected':''}>Workspace variables</option><option value="variant" ${scope==='variant'?'selected':''} ${S.variant===BASE?'disabled':''}>Variant overrides</option></select></div><div class="panel-body"><p class="fine">${scope==='project'?'These edits are staged. Review & native sync writes them to the project text_variables object.':'Export-only scope. Native sync is deliberately blocked while workspace/variant variables exist; move shared definitions to Project variables for native handoff.'}</p><div id="variableRows">${Object.entries(values).map(([k,v])=>variableRow(k,v)).join('')||variableRow()}</div><div class="row spread"><button class="small" data-act="addVariable">+ Variable</button><button class="primary small" data-act="saveVariables">Save variable changes</button></div></div></section><section class="panel"><div class="panel-title"><h2>Effective context</h2><span class="chip">${esc(S.variant)}</span></div><div class="panel-body"><dl class="keyvalue">${Object.entries(S.data.resolved_variables).map(([k,v])=>`<dt class="mono">${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')||'<dt>Variables</dt><dd>No custom variables defined</dd>'}</dl><div class="line"></div><h3>Expressions</h3><p class="fine"><code>\${NAME}</code> resolves recursively. Use <code>\${PROJECT:NAME}</code> for the effective custom-variable context, or <code>\${FIELD:MPN}</code> for a symbol field. <code>\${R1:MPN}</code> supports a one-hop reference lookup.</p><p class="fine">Context order: project → workspace → inherited variant overrides → sheet fields → symbol fields → supported built-ins. Cycles and unresolved names are release-blocking errors. Not every KiCad built-in expression is implemented.</p><p class="fine">Built-ins include PROJECTNAME, KIPRJMOD, VARIANT, VARIANT_DESC, REFERENCE, VALUE, FOOTPRINT, SHEETNAME, SHEETPATH, DNP and EXCLUDE_FROM_BOM.</p><button class="small" data-act="aliases">Manage field aliases</button></div></section></div>`;}
async function saveVariables(){const values={};for(const row of $$('#variableRows .variable-row')){const k=row.querySelector('[data-variable-key]').value.trim(),v=row.querySelector('[data-variable-value]').value;if(!k){if(v)throw Error('A variable value needs a name.');continue;}if(k in values)throw Error('Duplicate variable name: '+k);values[k]=v;}let overlay=values;if(S.variableScope==='project'){overlay={};for(const k of Object.keys(S.data.project_variables))if(!(k in values))overlay[k]=null;for(const [k,v]of Object.entries(values))if(S.data.project_variables[k]!==v)overlay[k]=v;}await action('variables',{scope:S.variableScope,values:overlay},'Variable changes staged in the workspace.');}
function renderSourcing(){const settings=S.data.settings;return `<div class="notice warning">Supplier prices, availability and lifecycle are manually entered or imported. No distributor API, live pricing, automatic qualification or PLM approval is implied.</div><section class="panel"><div class="panel-title"><h2>Build & purchasing assumptions</h2><button class="small" data-act="buildSettings">Edit build settings</button></div><div class="panel-body row"><span class="chip">${settings.boards} boards</span><span class="chip">${settings.attrition}% attrition</span><span class="chip">Default currency ${esc(settings.currency)}</span><span class="chip">Quote age threshold ${settings.quote_age_days} days</span><span class="grow"></span><button class="small" data-act="newAlternate">+ Record alternate</button><button class="primary small" data-view="exports">Purchasing export →</button></div><div class="table-wrap tall">${gridTable(S.data.rows.slice(0,250),['Reference','MPN','Manufacturer','Supplier','SKU','UnitPrice','Currency','Stock','MOQ','OrderMultiple','LeadTime','Lifecycle','PriceDate'],false)}</div></section><div class="spacer"></div><section class="panel"><div class="panel-title"><h2>Alternate decision register</h2></div><div class="panel-body">${Object.entries(S.data.alternates).map(([mpn,records])=>`<h3>${esc(mpn)}</h3>${records.map(r=>`<article class="variant-card"><div class="row spread"><strong>${esc(r.MPN)}</strong><span class="pill ${r.status==='approved'?'fit':r.status==='rejected'?'error':'warning'}">${esc(r.status)}</span></div><p class="fine">${esc(r.Manufacturer||'')} · ${esc(r.reviewer||'No reviewer')} · ${esc(r.updated||'')}</p><p class="fine">${esc(r.reason||'No compatibility note recorded')}</p></article>`).join('')}`).join('')||'<p class="muted">No alternate decisions recorded. Approving a candidate records a human decision; it does not substitute parts or verify pin compatibility automatically.</p>'}</div></section>`;}
function buildSettingsDialog(){const x=S.data.settings;showDialog('Build & validation settings',`<div class="field-row"><div class="field"><label>Number of boards</label><input type="number" name="boards" min="1" max="1000000" value="${x.boards}" required></div><div class="field"><label>Attrition / spare allowance (%)</label><input type="number" name="attrition" min="0" max="100" step="0.1" value="${x.attrition}" required></div></div><div class="field-row"><div class="field"><label>Default currency (3-letter code)</label><input name="currency" value="${esc(x.currency)}" maxlength="3" required></div><div class="field"><label>Maximum quote age (days)</label><input type="number" name="quote_age_days" min="1" max="3650" value="${x.quote_age_days}" required></div></div><div class="field"><label>Required fields for fitted BOM parts</label><input name="required_fields" value="${esc(x.required_fields.join(', '))}"><small>Comma-separated field names. Missing values block checked exports.</small></div><p class="fine">Required = ceiling(quantity per board × boards × (1 + attrition)). Order quantity respects MOQ and order multiple. Missing price remains unknown, not zero.</p>${formActions()}`,async f=>action('settings',{settings:{boards:Number(f.get('boards')),attrition:Number(f.get('attrition')),currency:f.get('currency').trim().toUpperCase(),quote_age_days:Number(f.get('quote_age_days')),required_fields:f.get('required_fields').split(',').map(x=>x.trim()).filter(Boolean)}},'Build assumptions updated.'));}
function alternateDialog(){showDialog('Record an alternate-part decision',`<p class="fine">This register never automatically replaces the primary MPN. Apply any reviewed substitution explicitly through the BOM editor in the intended variant.</p><div class="field"><label>Primary manufacturer / MPN or internal part identifier</label><input name="primary" required></div><div class="field-row"><div class="field"><label>Alternate MPN</label><input name="MPN" required></div><div class="field"><label>Manufacturer</label><input name="Manufacturer"></div></div><div class="field-row"><div class="field"><label>Decision</label><select name="status"><option>candidate</option><option>approved</option><option>rejected</option></select></div><div class="field"><label>Reviewer</label><input name="reviewer"></div></div><div class="field"><label>Compatibility / qualification note</label><textarea name="reason" placeholder="Package, pinout, ratings, derating, tests, qualification evidence…"></textarea></div>${formActions('Record decision')}`,async f=>action('alternate',{mpn:f.get('primary'),record:{MPN:f.get('MPN'),Manufacturer:f.get('Manufacturer'),status:f.get('status'),reviewer:f.get('reviewer'),reason:f.get('reason')}},'Alternate decision recorded. No part was automatically substituted.'));}
function templateColumn(c={field:'',label:''}){return `<div class="column-row"><input data-column-field aria-label="Column field" value="${esc(c.field)}" list="exportFieldNames"><input data-column-label aria-label="Column label" value="${esc(c.label)}"><button type="button" data-act="columnUp" aria-label="Move column up">↑</button><button type="button" data-act="columnDown" aria-label="Move column down">↓</button><button type="button" data-act="columnRemove" aria-label="Remove column">×</button></div>`;}
function renderExports(){if(!S.data.templates[S.template])S.template=Object.keys(S.data.templates)[0];const t=S.data.templates[S.template];return `<div class="split"><section class="panel"><div class="panel-title"><h2>Export configuration</h2></div><div class="template-form"><div class="field"><label>Saved template</label><select id="templateSelect">${Object.keys(S.data.templates).map(k=>`<option ${k===S.template?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="field"><label>Template name</label><input id="templateName" value="${esc(t.name)}"><small>Use a new name to save a reusable copy.</small></div><div class="field"><label>Population</label><select id="templatePopulation"><option value="all" ${t.population==='all'?'selected':''}>All population states</option><option value="fitted" ${t.population==='fitted'?'selected':''}>Fitted only</option><option value="not_fitted" ${t.population==='not_fitted'?'selected':''}>DNP / DNI only</option></select></div><label class="check-label"><input type="checkbox" id="templateExcluded" ${t.include_excluded?'checked':''}>Include parts excluded from BOM</label><div class="spacer"></div><div class="field"><label>Group by fields</label><input id="templateGroups" value="${esc(t.group_by.join(', '))}"><small>Comma-separated. Empty = one row per reference. Different MPNs, packages, prices and exported values are never silently merged.</small></div><div class="field-row"><div class="field"><label>CSV delimiter</label><select id="templateDelimiter">${[[',','Comma'],[';','Semicolon'],['\t','Tab'],['|','Pipe']].map(([v,l])=>`<option value="${esc(v==='\t'?'tab':v)}" ${t.delimiter===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Sort field</label><input id="templateSort" value="${esc(t.sort_field||'Reference')}"></div></div><label class="check-label"><input type="checkbox" id="templateRanges" ${t.ref_ranges?'checked':''}>Compact reference ranges</label><div class="column-head">SOURCE FIELD / EXPRESSION · COLUMN LABEL</div><div id="templateColumns">${t.columns.map(templateColumn).join('')}</div><datalist id="exportFieldNames">${[...new Set([...allFields(),...S.columns,'Qty','Required','OrderQty','LineCost','OrderCost','Item'])].map(k=>`<option value="${esc(k)}">`).join('')}</datalist><div class="row spread"><button class="small" data-act="addColumn">+ Column</button><button class="primary small" data-act="saveTemplate">Save template</button></div></div></section><section class="stack"><article class="panel"><div class="panel-title"><h2>Generate a BOM handoff</h2><button class="small" data-act="buildSettings">Build settings</button></div><div class="panel-body"><p class="fine">${S.data.settings.boards} boards · ${S.data.settings.attrition}% allowance · active variant ${esc(S.variant)}. Save template edits before previewing or exporting.</p><div class="row"><select id="exportFormat" aria-label="Export format"><option value="xlsx">Excel workbook (.xlsx)</option><option value="csv">CSV</option><option value="tsv">TSV</option><option value="json">JSON + metadata</option><option value="html">Printable HTML</option></select><button class="small" data-act="previewExport">Preview</button><button class="primary" data-act="downloadExport">Export active variant ↗</button></div><div class="spacer"></div><label class="check-label"><input id="draftExport" type="checkbox">Draft export — allow failed checks, mark as not for manufacturing</label><div class="line"></div><div class="row spread"><div><h3>All-variant release bundle</h3><p class="fine">CSV, XLSX, HTML, JSON, checks, workspace snapshot and SHA-256 manifest.</p></div><button class="secondary" data-act="downloadRelease">Build release ZIP</button></div><div class="notice warning">A BOM release is not a complete manufacturing release. PCB placement, Gerbers, package equivalence and ERC/DRC are not validated here.</div></div></article><article class="panel"><div class="panel-title"><h2>Output preview</h2><span class="chip">Saved template: ${esc(S.template)}</span></div><div id="exportPreview" class="panel-body"><p class="muted">Preview resolves variables, calculates order quantities, and runs release checks.</p></div></article></section></div>`;}
function collectTemplate(){const columns=$$('#templateColumns .column-row').map(r=>({field:r.querySelector('[data-column-field]').value.trim(),label:r.querySelector('[data-column-label]').value.trim()}));return {name:$('#templateName').value.trim(),columns,group_by:$('#templateGroups').value.split(',').map(x=>x.trim()).filter(Boolean),population:$('#templatePopulation').value,include_excluded:$('#templateExcluded').checked,delimiter:$('#templateDelimiter').value==='tab'?'\t':$('#templateDelimiter').value,ref_ranges:$('#templateRanges').checked,sort_field:$('#templateSort').value.trim()||'Reference'};}
async function previewExport(){const p=await api('export/preview',{variant:S.variant,template:S.template});$('#exportPreview').innerHTML=`<div class="row"><span class="chip">${p.groups} lines</span><span class="chip">${p.unpriced_lines} unpriced lines</span>${pill(p.issues.filter(i=>i.severity==='error').length+' errors')}</div><p class="fine">Order cost by currency: ${esc(JSON.stringify(p.order_totals))}</p><div class="table-wrap tall"><table class="data-table"><thead><tr>${p.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${p.rows.slice(0,100).map(r=>'<tr>'+r.map(c=>`<td>${esc(c)}</td>`).join('')+'</tr>').join('')}</tbody></table></div><p class="fine">Preview shows up to 100 lines. Exports include every line.</p>`;}
async function download(path,body){toast('Generating export…');const response=await fetch('/api/'+path,{method:'POST',headers:{'X-Bom-Token':token,'Content-Type':'application/json'},body:JSON.stringify({variant:S.variant,template:S.template,...body})});if(!response.ok){const err=await response.json();throw Error(err.error);}const file=await response.blob();const header=response.headers.get('Content-Disposition')||'';const name=decodeURIComponent(header.split("filename*=UTF-8''")[1]||'BOM-export');if(typeof saveBlob8==='function'){await saveBlob8(file,name);}else{const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}toast('Export generated. Review it before manufacturing or purchasing.');}
function renderChecks(){const errors=S.data.issues.filter(i=>i.severity==='error'),warnings=S.data.issues.filter(i=>i.severity==='warning');return `<div class="row spread"><div class="row">${pill(errors.length+' errors')}${pill(warnings.length+' warnings')}<span class="fine">Active variant only. A multi-variant release checks every included variant.</span></div><button class="small" data-act="buildSettings">Required fields & thresholds</button></div><div class="spacer"></div>${S.data.issues.length?`<div class="issues-list">${S.data.issues.map(i=>`<article class="issue">${pill(i.severity)}<strong>${esc(i.reference)}</strong><div>${esc(i.message)}<small>${esc(i.code)}</small></div></article>`).join('')}</div>`:'<div class="panel empty"><h2>No BOM-data checks are failing.</h2><p>This does not certify electrical design, pin compatibility, placement or supply-chain availability.</p></div>'}<div class="spacer"></div><div class="notice">Source changes outside this app require reopening the project. Save the workspace first; then reopen and review stale overrides before accepting a new source baseline.</div>`;}
function renderReview(){return `<div class="columns2"><section class="stack"><article class="panel"><div class="panel-title"><h2>Workspace checkpoints</h2></div><div class="panel-body"><p class="fine">Save workspace writes only <code>.wayricad-bom.json</code>. Native KiCad files stay untouched until reviewed sync.</p><div class="row"><button class="primary small" data-act="save">Save workspace</button><button class="small" data-act="baseline">Capture BOM baseline</button><button class="small" data-act="baselineDiff">Compare to baseline</button></div><p class="fine">${S.data.baseline?.time?'Baseline: '+esc(S.data.baseline.time)+' · '+esc(S.data.baseline.variant):'No BOM baseline captured.'}</p><div id="baselineResults"></div><div class="line"></div><div class="row"><button class="small" data-act="reload">Reopen source files</button><button class="small" data-act="upgradeCopy">Upgrade project copy</button><button class="small" data-act="rebase">Acknowledge source changes…</button></div></div></article><article class="panel"><div class="panel-title"><h2>Workspace activity</h2><span class="chip">Not a signed approval log</span></div><div class="panel-body scroll-card">${S.data.history.slice(-40).reverse().map(h=>`<p><b class="fine">${esc(h.action)}</b><br><span class="fine">${esc(h.time)}</span></p>`).join('')||'<p class="muted">No workspace changes yet.</p>'}</div></article></section><section class="panel"><div class="panel-title"><h2>Native KiCad sync</h2><span class="pill ${S.data.project.native_write_supported?'fit':'warning'}">${S.data.project.native_write_supported?'Format supported':'Blocked by adapter'}</span></div><div class="panel-body"><p class="fine">Writes supported symbol fields, population/inclusion flags, project variables and variant records. Inherited workspace variants become native differentials. No wires, geometry, UUIDs or PCB records are deliberately changed.</p><div class="notice warning"><b>Close all KiCad editors before applying.</b> Unsaved editor changes are not visible here. After sync, reopen the project, inspect it, and run <b>Update PCB from Schematic</b>. Start with a copy of your project.</div><button class="primary" data-act="nativePreview">Review proposed native changes</button><div class="spacer"></div><div id="nativePreview"><p class="muted">A preview must be generated before Apply becomes available.</p></div></div></section></div>`;}
function upgradeCopy(){showDialog('Upgrade project copy',`<p>Use installed KiCad 10 to upgrade every sheet while preserving native connectivity, annotation and component fields. The original project is unchanged. This can take a few minutes for a large hierarchy.</p><div class="field"><label>New destination directory</label><input name="destination" required placeholder="C:/Projects/Board-upgraded"></div>${formActions('Upgrade and open copy')}`,async f=>{const destination=f.get('destination').trim();if(!destination)throw Error('Enter a new destination directory.');await api('upgrade-copy',{destination});S.variant=BASE;S.selected.clear();S.preview=null;await refresh();toast('Verified upgraded project copy opened.');});}
async function nativePreview(){const p=await api('native/preview',{});S.preview=p;$('#nativePreview').innerHTML=`<p><b>${p.count} native file${p.count===1?'':'s'} would change.</b></p>${p.files.map(f=>`<details><summary>${esc(f.path)}</summary><pre class="diff">${esc(f.diff||'No content difference')}</pre></details>`).join('')}<p class="fine">The sidecar is also checkpointed during Apply. Existing files are backed up before replacement. Ordinary exceptions trigger rollback; a power loss can still require manual recovery from the manifest.</p>${p.count?'<button class="danger" data-act="nativeApply">Apply reviewed native changes…</button>':'<p class="fine">No native changes are pending.</p>'}`;}
function applyNativeDialog(){if(!S.preview)throw Error('Generate a fresh preview first.');showDialog('Apply changes to native KiCad files',`<div class="notice warning">This changes the original project and schematic files. Keep a separate project copy / Git commit, and review the diffs above first.</div><label class="check-label"><input name="closed" type="checkbox" required>All KiCad editors for this project are closed</label><div class="spacer"></div><div class="field"><label>Type APPLY to confirm</label><input name="confirmation" required autocomplete="off"></div>${formActions('Apply with backups')}`,async f=>{const p=await api('native/apply',{fingerprint:S.preview.fingerprint,confirmation:f.get('confirmation'),editors_closed:f.has('closed')});S.preview=null;await refresh();toast('Native sync complete. Backups: '+p.backup);});}
function renderAbout(){return `<div class="columns2"><section class="panel"><div class="panel-title"><h2>Compatibility</h2></div><div class="panel-body"><div id="compatibility">Discovering local CLI capabilities…</div><div class="line"></div><h3>KiCad 10</h3><p class="fine">This standalone process can be launched by a KiCad IPC action. It reads saved files and does not depend on deprecated pcbnew/SWIG bindings. With the optional official Python client and inherited IPC context, it discovers a saved PCB project and offers a selection-only live link. Otherwise select the root project explicitly. BOM data still comes from saved files, not unsaved editor memory.</p><h3>KiCad 11 readiness</h3><p class="fine">Adapter separation, capability probing, and fail-closed checks prepare for evolution. Unknown future file versions and variant tokens are inspection-only, not presumed compatible.</p><h3>Deliberate exclusions in this preview</h3><p class="fine">Flat multiple-root projects, embedded child sheets, rule-area-derived population, ambiguous annotation, cross-sheet multi-unit grouping, unsupported expressions and unknown variant tokens are not guessed. Some are blocked at open, others block checked output and native sync.</p><p class="fine">Saved KiCad BOM settings are followed by default. Custom copies and reverse synchronization require explicit review. Native variant deletion/renaming remains in KiCad. Workspace-only variants can be removed here.</p></div></section><section class="panel"><div class="panel-title"><h2>Everyday workflow</h2></div><div class="panel-body"><h3>1 · Open a saved project</h3><p class="fine">Use a copy first. Resolve annotation / hierarchy problems and inspect Checks. Workspace sidecars are suitable for Git alongside the project.</p><h3>2 · Set assembly intent</h3><p class="fine">Create a variant, select parts, choose FIT / DNP / DNI, and edit fields. BOM, placement and board inclusion are independent flags. Inspect ↗ shows raw values and provenance.</p><h3>3 · Prepare purchasing data</h3><p class="fine">Import CSV with a Reference column. Preview changes, maintain manual price dates, and set board quantity and required fields. CSV imports never automatically approve alternate parts.</p><h3>4 · Export or sync deliberately</h3><p class="fine">Save workspace; generate checked exports, or explicit drafts. Native sync is optional, reviewed and backed up. It does not replace KiCad's native electrical checks.</p><div class="line"></div><h3>Security & ownership</h3><p class="fine">Localhost-only random-port server; per-session API token; no CDN, telemetry, account, cloud storage or supplier credentials. The local API token is not a defense against malicious software already running as you. Release bundles can contain local file paths and proprietary fields; inspect before sharing.</p><p class="fine">Closing the embedded window confirms unsaved work and stops its server. In browser mode, closing a tab does not stop the server: use Quit. Undo is session-local; the saved sidecar includes a change history, not enforceable multi-user approvals.</p><button class="small" data-act="demo">Open temporary sample project</button></div></section></div>`;}
async function loadCompatibility(){try{const x=await api('compat');if(!$('#compatibility'))return;$('#compatibility').innerHTML=`<dl class="keyvalue"><dt>Python</dt><dd>${esc(x.python)}</dd><dt>KiCad CLI</dt><dd>${esc(x.cli_version)}</dd><dt>CLI variant flag</dt><dd>${x.native_bom_variant_flag?'Detected':'Not detected'}</dd><dt>Native write format</dt><dd>${x.native_write_format}</dd><dt>Runtime</dt><dd>${x.ipc_runtime?'KiCad IPC-launched process':'Standalone local process'}</dd><dt>Live schematic editing</dt><dd>Not used</dd></dl><p class="fine">${esc(x.error)}</p><p class="fine">${S.data.project.native_presets.length} native BOM presets detected.</p>`;}catch(e){if($('#compatibility'))$('#compatibility').textContent=e.message;}}
function importDialog(){showDialog('Preview a CSV field import',`<p class="fine">Use a Reference / Designator column. Multiple references may be comma-separated in a quoted cell; compressed ranges such as R1–R8 are not accepted. Unknown references and duplicate assignments block import.</p><div class="field"><label>Choose CSV / TSV file</label><input type="file" id="csvFile" accept=".csv,.tsv,.txt"></div><div class="field"><label>Or paste table text</label><textarea id="csvText" rows="7" placeholder="Reference,MPN,UnitPrice,Currency&#10;R1,YourPart,2.40,INR"></textarea></div><button data-act="importPreview" class="primary">Preview changes</button><div id="csvPreview"></div>`);$('#csvFile').addEventListener('change',async e=>{const file=e.target.files[0];if(file){if(file.size>10*1024*1024){toast('CSV exceeds 10 MiB.',true);return;}$('#csvText').value=await file.text();}});}
async function importPreview(){const text=$('#csvText').value,plan=await api('import/preview',{variant:S.variant,text});S.importText=text;$('#csvPreview').innerHTML=`<div class="spacer"></div><p><b>${plan.count} component edits</b> · ${plan.unmatched.length} unmatched references</p>${plan.unmatched.length?`<div class="notice error">Unmatched: ${esc(plan.unmatched.join(', '))}</div>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Proposed fields</th></tr></thead><tbody>${plan.changes.slice(0,100).map(c=>`<tr><td>${esc(c.ref)}</td><td class="wrap">${esc(JSON.stringify(c.changes))}</td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="primary" data-act="importApply" ${plan.unmatched.length||!plan.count?'disabled':''}>Apply ${plan.count} changes</button></div>`;}
function aliasesDialog(){showDialog('Field-name aliases',`<p class="fine">One canonical field per line: name = alias 1, alias 2. Canonical fields take precedence. These rules only affect workspace interpretation and exports; source fields are not silently renamed.</p><textarea name="aliases" rows="14">${esc(Object.entries(S.data.aliases).map(([k,v])=>k+' = '+v.join(', ')).join('\n'))}</textarea>${formActions('Save aliases')}`,async f=>{const aliases={};for(const line of f.get('aliases').split('\n').filter(x=>x.trim())){const index=line.indexOf('=');if(index<1)throw Error('Use canonical = alias 1, alias 2');const key=line.slice(0,index).trim();if(key in aliases)throw Error('Duplicate canonical field: '+key);aliases[key]=line.slice(index+1).split(',').map(x=>x.trim()).filter(Boolean);}await action('aliases',{aliases},'Field interpretation rules updated.');});}
async function save(){if(S.formDirty&&S.view==='variables')await saveVariables();if(S.formDirty&&S.view==='exports')await ensureTemplateSaved();if(S.formDirty&&S.view==='fieldtemplates')await saveFieldProfile(false);await action('save',{},r=>'Workspace saved: '+r.path);}
async function populationMatrix(){const m=await api('matrix',{});const names=m.variants.slice(0,32);$('#variantComparison').innerHTML=`<p class="fine">Click a population cell to edit. Sheet restrictions still take precedence. Showing up to 250 parts and 32 variants.</p><div class="table-wrap tall"><table class="data-table"><thead><tr><th>Reference</th>${names.map(v=>`<th>${esc(v===BASE?'Default':v)}</th>`).join('')}</tr></thead><tbody>${m.rows[BASE].slice(0,250).map((r,i)=>`<tr><td class="ref">${esc(r.reference)}</td>${names.map(v=>{const c=m.rows[v][i];return `<td class="matrix-cell"><button data-matrix-id="${esc(r.id)}" data-matrix-variant="${esc(v)}" data-matrix-state="${esc(c.state)}" title="${esc(c.inherited.join(', ')||'Local population')}">${pill(c.state)}</button>${c.in_bom?'':' <small>BOM off</small>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}

async function switchVariant(v){if(S.formDirty&&!confirm('Discard unsaved form edits before changing variant?')){$('#activeVariant').value=S.variant;return;}if(!confirmPendingGrid()){$('#activeVariant').value=S.variant;return;}S.variant=v;S.selected.clear();S.page=0;S.preview=null;if(v===BASE&&S.variableScope==='variant')S.variableScope='project';await refresh();}
const handlers={
 closeDialog:()=>$('#dialog').close(),browse:async()=>{const r=await api('browse',{});if(r.path)$('#projectInput').value=r.path;},
 demo:async()=>{if(S.data?.dirty&&!confirm('Discard unsaved workspace changes and open a sample copy?'))return;await api('open',{demo:true,discard:true});$('#dialog').close();S.variant=BASE;S.view='bom';S.selected.clear();await refresh();},
 save,undo:()=>action('undo',{},'Undo applied.'),redo:()=>action('redo',{},'Redo applied.'),columns:columnsDialog,bulk:()=>editDialog(),import:importDialog,
 clearSelection:()=>{S.selected.clear();render();},prevPage:()=>{S.page--;render();},nextPage:()=>{S.page++;render();},newVariant:newVariantDialog,
 populationMatrix,compareVariants:async()=>{$('#variantComparison').innerHTML=diffTable((await api('compare',{left:$('#compareLeft').value,right:$('#compareRight').value})).changes);},
 addVariable:()=>{S.formDirty=true;$('#variableRows').insertAdjacentHTML('beforeend',variableRow());},removeVariable:el=>{S.formDirty=true;el.closest('.variable-row').remove();},saveVariables,aliases:aliasesDialog,
 buildSettings:buildSettingsDialog,newAlternate:alternateDialog,addColumn:()=>{S.formDirty=true;$('#templateColumns').insertAdjacentHTML('beforeend',templateColumn());},
 columnRemove:el=>{S.formDirty=true;el.closest('.column-row').remove();},columnUp:el=>{S.formDirty=true;const r=el.closest('.column-row');if(r.previousElementSibling)r.parentNode.insertBefore(r,r.previousElementSibling);},columnDown:el=>{S.formDirty=true;const r=el.closest('.column-row');if(r.nextElementSibling)r.parentNode.insertBefore(r.nextElementSibling,r);},
 saveTemplate:async()=>{const template=collectTemplate();await api('template',{template});S.template=template.name;await refresh();toast('Export template saved to the workspace.');},previewExport,
 downloadExport:()=>download('export',{format:$('#exportFormat').value,draft:$('#draftExport').checked}),downloadRelease:()=>download('release',{draft:$('#draftExport').checked}),
 baseline:()=>action('baseline',{},'BOM baseline captured in the workspace.'),baselineDiff:async()=>{$('#baselineResults').innerHTML=diffTable((await api('baseline/diff',{variant:S.variant})).changes);},
 reload:async()=>{if(S.data.dirty&&!confirm('Discard unsaved workspace changes before reopening source files?'))return;await api('reload',{discard:true,variant:S.variant});await refresh();toast('Source files reopened. Review any stale-baseline checks.');},
 rebase:()=>showDialog('Acknowledge a changed source baseline',`<div class="notice warning">Review source-file differences in Git/KiCad, and verify all pending workspace overrides first. This acknowledgement does not automatically reconcile conflicting design intent.</div><div class="field"><label>Type REBASE to accept the current saved source files</label><input name="confirmation" required></div>${formActions('Acknowledge baseline')}`,async f=>action('rebase',{confirmation:f.get('confirmation')},'Source baseline acknowledged.')),
 upgradeCopy,nativePreview,nativeApply:applyNativeDialog,importPreview,importApply:async()=>{await action('import/apply',{text:S.importText},r=>`${r.affected} CSV component edits applied.`);$('#dialog').close();}
};
document.addEventListener('click',async event=>{const el=event.target.closest('button,[data-view]');if(!el)return;try{if(el.dataset.view){if(S.formDirty&&!confirm('Discard unsaved form edits? Save this form to keep them.'))return;S.view=el.dataset.view;render();return;}if(el.dataset.matrixId){const ids=[el.dataset.matrixId],variant=el.dataset.matrixVariant;showDialog('Population in '+variant,`<p class="fine">DNP / DNI do not automatically change BOM or placement inclusion.</p><div class="field"><label>Population</label><select name="state">${['FIT','DNP','DNI'].map(s=>`<option ${s===el.dataset.matrixState?'selected':''}>${s}</option>`).join('')}</select></div>${formActions('Apply to variant')}`,async f=>{await api('population',{ids,variant,state:f.get('state')});await refresh();await populationMatrix();toast('Variant population updated.');});return;}if(el.dataset.act){await handlers[el.dataset.act]?.(el);return;}if(el.dataset.pop){await action('population',{ids:[...S.selected],state:el.dataset.pop},r=>`${r.affected} component instances updated.`);return;}if(el.dataset.inspect){inspect(el.dataset.inspect);return;}if(el.dataset.chooseVariant){await switchVariant(el.dataset.chooseVariant);return;}if(el.dataset.removeVariant){if(confirm('Remove workspace variant '+el.dataset.removeVariant+'?')){const name=el.dataset.removeVariant;await api('variant/remove',{name});if(S.variant===name)S.variant=BASE;await refresh();}return;}if(el.dataset.sort){S.asc=S.sort===el.dataset.sort?!S.asc:true;S.sort=el.dataset.sort;render();}}catch(e){toast(e.message,true);}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='activeVariant')await switchVariant(el.value);if(el.id==='populationFilter'){S.filter=el.value;S.page=0;render();}if(el.dataset.select){if(el.checked)S.selected.add(el.dataset.select);else S.selected.delete(el.dataset.select);render();}if(el.id==='selectPage'){const rows=filteredRows().slice(S.page*S.pageSize,(S.page+1)*S.pageSize);for(const r of rows)if(el.checked)S.selected.add(r.id);else S.selected.delete(r.id);render();}if(el.id==='variableScope'){if(S.formDirty&&!confirm('Discard unsaved variable edits?')){el.value=S.variableScope;return;}S.variableScope=el.value;render();}if(el.id==='templateSelect'){if(S.formDirty&&!confirm('Discard unsaved template edits?')){el.value=S.template;return;}S.template=el.value;render();}if(el.closest('.template-form')&&el.id!=='templateSelect')S.formDirty=true;}catch(e){toast(e.message,true);}});
let searchTimer;document.addEventListener('input',event=>{if(event.target.closest('#variableRows,.template-form'))S.formDirty=true;if(event.target.id==='search'){clearTimeout(searchTimer);const value=event.target.value,pos=event.target.selectionStart;searchTimer=setTimeout(()=>{S.search=value;S.page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);},150);}});
document.addEventListener('dblclick',event=>{const c=event.target.closest('td.editable');if(c)editDialog([c.dataset.id],c.dataset.field);});
document.addEventListener('keydown',async event=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName);try{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();if(S.data?.project)await save();}if(!editing&&!$('#dialog').open&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();await action(event.shiftKey?'redo':'undo',{},event.shiftKey?'Redo applied.':'Undo applied.');}if(!editing&&!$('#dialog').open&&event.key==='/'){event.preventDefault();if(S.formDirty&&!confirm('Discard unsaved form edits? Save this form to keep them.'))return;S.view='bom';render();$('#search')?.focus();}if(!editing&&!$('#dialog').open&&event.key==='Enter'&&S.selected.size)editDialog();}catch(e){toast(e.message,true);}});
$('#openButton').addEventListener('click',openDialog);$('#welcomeOpen')?.addEventListener('click',openDialog);$('#welcomeDemo')?.addEventListener('click',()=>handlers.demo().catch(e=>toast(e.message,true)));$('#saveButton').addEventListener('click',()=>save().catch(e=>toast(e.message,true)));$('#quickExport').addEventListener('click',()=>{if(S.view==='exports')return;if(S.formDirty&&!confirm('Discard unsaved form edits? Save this form to keep them.'))return;S.view='exports';render();});$('#dialogClose').addEventListener('click',()=>$('#dialog').close());
$('#quitButton').addEventListener('click',async()=>{if((S.data?.dirty||S.formDirty)&&!confirm('Quit and discard unsaved workspace changes?'))return;try{await api('quit',{discard:true});document.body.innerHTML='<main class="welcome"><h1>Workspace closed.</h1><p>The local server has stopped. You can close this tab.</p></main>';}catch(e){toast(e.message,true);}});
$('#themeButton').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;localStorage.setItem('wayricadTheme',theme);});document.documentElement.dataset.theme=localStorage.getItem('wayricadTheme')||'light';
window.addEventListener('beforeunload',event=>{if(S.data?.dirty||S.formDirty){event.preventDefault();event.returnValue='';}});
